<template>
  <section><div class="page-heading"><div><p class="eyebrow">نقطة البيع</p><h1>فاتورة جديدة</h1><span class="hint">اختر منتجاً لإضافته إلى السلة</span></div><button class="outline" @click="seedDemo">＋ بيانات تجريبية</button></div><div class="pos-grid"><div class="panel products-panel"><div class="toolbar"><input v-model="query" autofocus placeholder="🔎 ابحث بالاسم أو الباركود..." @keyup.enter="focusFirst" /><select v-model="currency"><option value="YER">ريال يمني</option><option value="SAR">ريال سعودي</option><option value="USD">دولار أمريكي</option></select></div><div class="product-grid"><button v-for="(p,i) in filteredProducts" :key="p._id" :ref="el=>{if(i===0) firstProduct=el as HTMLButtonElement}" class="product-card" @click="add(p)"><span class="product-icon">▦</span><strong>{{ p.name_ar }}</strong><small>{{ p.stock }} متوفر</small><b>{{ money(p.sell_price,p.currency) }}</b></button></div><div v-if="!filteredProducts.length" class="empty">لا توجد نتائج. أضف منتجاً أو حمّل البيانات التجريبية.</div></div><div class="panel invoice-panel"><div class="panel-title"><h2>تفاصيل الفاتورة</h2><span class="badge">{{ cart.length }} أصناف</span></div><div class="cart-lines"><div v-for="line in cart" :key="line._id" class="cart-line"><div><strong>{{ line.name_ar }}</strong><small>{{ money(line.sell_price,currency) }}</small></div><div class="qty"><button @click="changeQty(line._id,-1)">−</button><b>{{ line.qty }}</b><button @click="changeQty(line._id,1)">＋</button></div><strong>{{ money(line.lineTotal,currency) }}</strong></div><div v-if="!cart.length" class="empty">السلة فارغة<br /><small>ابدأ بإضافة منتج</small></div></div><div class="summary"><div><span>المجموع الفرعي</span><b>{{ money(subtotal,currency) }}</b></div><div><span>الخصم</span><input v-model.number="discount" type="number" min="0" /></div><div class="grand"><span>الإجمالي</span><b>{{ money(total,currency) }}</b></div></div><div class="payment"><label>طريقة الدفع</label><div class="payment-options"><button v-for="method in methods" :key="method.id" :class="{selected:payment===method.id}" @click="payment=method.id">{{ method.label }}</button></div></div><button class="primary full" :disabled="!cart.length" @click="saveInvoice">حفظ الفاتورة محلياً</button><button class="outline full" :disabled="!cart.length" @click="print">🖨 طباعة الفاتورة</button></div></div></section>
</template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import db,{type Currency,type Product} from '../services/pouchdb';import {printViaBluetooth} from '../services/printer'
const products=ref<Product[]>([]),cart=ref<Array<Product&{qty:number;lineTotal:number}>>([]),query=ref(''),currency=ref<Currency>('YER'),discount=ref(0),payment=ref<'cash'|'wallet'|'credit'>('cash'),firstProduct=ref<HTMLButtonElement>()
const methods=[{id:'cash',label:'نقدي'},{id:'wallet',label:'محفظة'},{id:'credit',label:'آجل'}] as const;const filteredProducts=computed(()=>products.value.filter(p=>`${p.name_ar} ${p.name_en} ${p.barcode||''}`.toLowerCase().includes(query.value.toLowerCase())));const subtotal=computed(()=>cart.value.reduce((s,p)=>s+p.lineTotal,0));const total=computed(()=>Math.max(0,subtotal.value-Number(discount.value||0)));const money=(v:number,c:Currency)=>new Intl.NumberFormat('ar-YE',{style:'currency',currency:c,maximumFractionDigits:0}).format(v)
function focusFirst(){firstProduct.value?.focus()}function add(p:Product){const line=cart.value.find(x=>x._id===p._id);if(line)line.qty++;else cart.value.push({...p,qty:1,lineTotal:p.sell_price});recalc()}function changeQty(id:string,d:number){const line=cart.value.find(x=>x._id===id);if(!line)return;line.qty+=d;if(line.qty<=0)cart.value=cart.value.filter(x=>x._id!==id);recalc()}function recalc(){cart.value.forEach(x=>x.lineTotal=x.qty*x.sell_price)}async function load(){products.value=await db.list<Product>('product')}async function seedDemo(){for(const p of [{_id:'product:coffee',type:'product',name_ar:'قهوة محمصة',name_en:'Roasted Coffee',sell_price:1800,cost_price:1200,stock:24,min_stock:5,currency:'YER'},{_id:'product:water',type:'product',name_ar:'مياه معدنية',name_en:'Mineral Water',sell_price:300,cost_price:180,stock:7,min_stock:10,currency:'YER'},{_id:'product:tea',type:'product',name_ar:'شاي فاخر',name_en:'Premium Tea',sell_price:2500,cost_price:1700,stock:16,min_stock:4,currency:'YER'}] as Product[]){try{await db.put(p)}catch{}}await load()}async function saveInvoice(){const now=new Date().toISOString();await db.put({_id:`sale:${Date.now()}`,type:'sale',lines:cart.value,subtotal:subtotal.value,discount:Number(discount.value||0),total:total.value,currency:currency.value,payment_method:payment.value,created_at:now,synced:false});for(const line of cart.value){const p=await db.get(line._id) as Product;await db.put({...p,stock:Math.max(0,p.stock-line.qty)})}cart.value=[];discount.value=0;await load();alert('تم حفظ الفاتورة محلياً بنجاح')}async function print(){await printViaBluetooth({text:`محاسبي\nالإجمالي: ${money(total.value,currency.value)}\nطريقة الدفع: ${payment.value}`})}onMounted(load)
</script>
<style scoped>.hint{color:var(--muted);font-size:11px}.pos-grid{display:grid;grid-template-columns:1fr 410px;gap:20px}.product-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:12px}.product-card{border:1px solid var(--line);background:#fff;border-radius:13px;padding:15px;text-align:right;display:grid;gap:4px;cursor:pointer;font-family:inherit}.product-card:hover{border-color:var(--primary);box-shadow:0 7px 15px #159a8c14;transform:translateY(-2px)}.product-icon{color:var(--primary);font-size:25px}.product-card small,.cart-line small{display:block;color:var(--muted);font-size:11px}.product-card b{color:var(--primary);margin-top:5px}.cart-lines{min-height:200px}.cart-line{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;border-bottom:1px solid var(--line);padding:12px 0;font-size:12px}.qty{display:flex;gap:8px;align-items:center}.qty button{border:0;background:#edf2f7;border-radius:6px;width:25px;height:25px;cursor:pointer}.summary{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}.summary>div{display:flex;justify-content:space-between;align-items:center;margin:7px 0;font-size:12px}.summary input{width:100px}.summary .grand{font-size:18px;color:var(--primary);font-weight:800;margin-top:15px}.payment{margin:17px 0}.payment label{font-size:12px;display:block;margin-bottom:8px}.payment-options{display:flex;gap:6px}.payment-options button{flex:1;padding:8px;border:1px solid var(--line);background:#fff;border-radius:8px;font-family:inherit;font-size:11px;cursor:pointer}.payment-options button.selected{border-color:var(--primary);color:var(--primary);background:var(--primary-pale)}.full{width:100%;margin-top:8px}@media(max-width:900px){.pos-grid{grid-template-columns:1fr}.invoice-panel{order:-1}}
</style>
